import{c as a,$ as d,Q as i,j as l,g as e,n as u,o as c,m as n}from"./chunks/framework.Xjf2pjgg.js";const k=JSON.parse('{"title":"YuRelic 权限节点","description":"","frontmatter":{"title":"YuRelic 权限节点"},"headers":[],"relativePath":"plugins/items/yu-relic/permissions.md","filePath":"plugins/items/yu-relic/permissions.md"}'),s={name:"plugins/items/yu-relic/permissions.md"},h={class:"quick-actions"};function y(b,t,p,m,_,x){const r=d("CopyMarkdownButton"),o=d("CopyLLMButton");return i(),l("div",null,[t[0]||(t[0]=e("h1",{id:"yurelic-权限节点",tabindex:"-1"},[u("YuRelic 权限节点 "),e("a",{class:"header-anchor",href:"#yurelic-权限节点","aria-label":'Permalink to "YuRelic 权限节点"'},"​")],-1)),e("div",h,[c(r,{page:""}),c(o,{page:""})]),t[1]||(t[1]=n('<p>YuRelic 的权限可以按“玩家玩法、系统功能、管理运维、高危操作、倍率”分层分配。普通玩家不需要获得全部节点，建议按服务器开放的玩法逐步授予。</p><h2 id="玩家基础" tabindex="-1">玩家基础 <a class="header-anchor" href="#玩家基础" aria-label="Permalink to &quot;玩家基础&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>节点</th><th>用途</th></tr></thead><tbody><tr><td>基础</td><td><code>yurelic.use</code></td><td>使用 YuRelic 基础能力。</td></tr><tr><td>开光</td><td><code>yurelic.open</code></td><td>将可识别物品开光为灵器。</td></tr><tr><td>展示</td><td><code>yurelic.share</code></td><td>分享灵器信息。</td></tr><tr><td>修复</td><td><code>yurelic.repair</code></td><td>使用器体修复能力。</td></tr><tr><td>GUI</td><td><code>yurelic.gui</code></td><td>打开玩家菜单或系统入口。</td></tr></tbody></table><h2 id="成长玩法" tabindex="-1">成长玩法 <a class="header-anchor" href="#成长玩法" aria-label="Permalink to &quot;成长玩法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>节点</th></tr></thead><tbody><tr><td>成长主线</td><td><code>yurelic.breakthrough</code>、<code>yurelic.pact</code>、<code>yurelic.affinity</code></td></tr><tr><td>器魂与天赋</td><td><code>yurelic.soul</code>、<code>yurelic.talent</code>、<code>yurelic.awaken</code>、<code>yurelic.potential</code></td></tr><tr><td>道韵精通</td><td><code>yurelic.mastery</code></td></tr></tbody></table><h2 id="系统模块" tabindex="-1">系统模块 <a class="header-anchor" href="#系统模块" aria-label="Permalink to &quot;系统模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>节点</th></tr></thead><tbody><tr><td>饰品与图鉴</td><td><code>yurelic.accessory</code>、<code>yurelic.codex</code></td></tr><tr><td>试炼与套装</td><td><code>yurelic.trial</code>、<code>yurelic.sets</code></td></tr><tr><td>铭纹与里程碑</td><td><code>yurelic.glyph</code>、<code>yurelic.milestone</code></td></tr><tr><td>器势、灵潮、器愿、灵息</td><td><code>yurelic.stance</code>、<code>yurelic.tide</code>、<code>yurelic.vow</code>、<code>yurelic.breath</code></td></tr><tr><td>生命周期</td><td><code>yurelic.heritage</code>、<code>yurelic.seal</code>、<code>yurelic.title</code>、<code>yurelic.salvage</code>、<code>yurelic.guard</code></td></tr><tr><td>展示与经济</td><td><code>yurelic.market</code>、<code>yurelic.blessing</code>、<code>yurelic.archive</code>、<code>yurelic.rank</code>、<code>yurelic.appraise</code></td></tr><tr><td>掉落与战斗</td><td><code>yurelic.loot</code>、<code>yurelic.scene</code>、<code>yurelic.combat</code>、<code>yurelic.resource</code>、<code>yurelic.shop</code></td></tr></tbody></table><h2 id="管理与运维" tabindex="-1">管理与运维 <a class="header-anchor" href="#管理与运维" aria-label="Permalink to &quot;管理与运维&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>用途</th></tr></thead><tbody><tr><td><code>yurelic.debug</code></td><td>调试物品识别、数据或内部状态。</td></tr><tr><td><code>yurelic.hooks</code></td><td>查看软依赖联动状态。</td></tr><tr><td><code>yurelic.libs</code></td><td>查看动态依赖加载状态。</td></tr><tr><td><code>yurelic.storage</code></td><td>查看存储与数据库状态。</td></tr><tr><td><code>yurelic.integrity</code></td><td>查看物品完整性和防复制相关状态。</td></tr><tr><td><code>yurelic.diagnose</code></td><td>使用 Doctor 诊断能力。</td></tr><tr><td><code>yurelic.reload</code></td><td>重载配置。</td></tr></tbody></table><h2 id="高危管理" tabindex="-1">高危管理 <a class="header-anchor" href="#高危管理" aria-label="Permalink to &quot;高危管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>风险</th></tr></thead><tbody><tr><td><code>yurelic.open.admin</code></td><td>可能绕过普通开光限制。</td></tr><tr><td><code>yurelic.pact.admin</code></td><td>可处理灵契归属。</td></tr><tr><td><code>yurelic.rank.admin</code></td><td>可管理天榜或排名数据。</td></tr><tr><td><code>yurelic.resource.admin</code></td><td>可调整灵材资源。</td></tr><tr><td><code>yurelic.exp.admin</code></td><td>可调整经验和成长进度。</td></tr><tr><td><code>yurelic.item.admin</code></td><td>可操作灵器物品数据。</td></tr><tr><td><code>yurelic.purge</code></td><td>可清理或抹除灵器身份，建议只给核心管理员。</td></tr></tbody></table><h2 id="倍率权限" tabindex="-1">倍率权限 <a class="header-anchor" href="#倍率权限" aria-label="Permalink to &quot;倍率权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>节点</th><th>说明</th></tr></thead><tbody><tr><td><code>yurelic.exp.multiplier.*</code></td><td>经验倍率通配。</td></tr><tr><td><code>yurelic.exp.multiplier.2</code></td><td>示例：2 倍经验。</td></tr><tr><td><code>yurelic.exp.multiplier.5</code></td><td>示例：5 倍经验。</td></tr></tbody></table><h2 id="分配建议" tabindex="-1">分配建议 <a class="header-anchor" href="#分配建议" aria-label="Permalink to &quot;分配建议&quot;">​</a></h2><ul><li>生存服可以先开放 <code>use</code>、<code>open</code>、<code>repair</code>、<code>gui</code>、<code>share</code>，再按玩法逐步开放突破、器魂和饰品。</li><li>RPG 服通常需要开放成长主线与掉落战斗相关节点，但高危管理节点仍应独立给管理员。</li><li>不建议把 <code>yurelic.purge</code>、<code>yurelic.item.admin</code>、<code>yurelic.resource.admin</code> 放入普通管理组。</li></ul>',15))])}const f=a(s,[["render",y]]);export{k as __pageData,f as default};
